def extract_time_components(s: str) -> list[tuple[str, str]]:
    import re

    units = {'d', 'h', 'm', 's'}

    # 使用正则表达式匹配所有时间部分
    time_pattern = r'\d+([dhms])?'
    matches = re.findall(time_pattern, s)

    components = []
    for match in matches:
        if not match:  # 空字符串情况
            raise ValueError("Invalid format")

        num_str, unit = '', 's'  # 默认单位为秒

        if len(match) == 1 and match[0] in units:
            num_str = '1'
            unit = match[0]
        elif len(match) > 1:
            for i, c in enumerate(match):
                if c.isdigit():
                    num_str += c
                else:
                    unit = c
                    break

        if not num_str or not unit or unit not in units:
            raise ValueError("Invalid format")

        components.append((num_str, unit))

    return components

def calculate_total_seconds(components: list[tuple[str, str]]) -> int:
    units = {
        'd': 86400,
        'h': 3600,
        'm': 60,
        's': 1
    }

    total_seconds = 0

    for num_str, unit in components:
        try:
            value = int(num_str)
            if value < 0:
                raise ValueError("Negative values are not allowed")
            total_seconds += value * units[unit]
        except KeyError:
            raise ValueError(f"Unknown unit: {unit}")
        except ValueError:
            raise ValueError("Invalid number format")

    return total_seconds
