def _parse_units(s: str) -> list[tuple[float, str]]:
    parsed_units = []
    i = 0
    while i < len(s):
        num_str = ''
        while i < len(s) and s[i].isdigit():
            num_str += s[i]
            i += 1

        if not num_str:
            raise ValueError("Invalid duration format")

        num = float(num_str)

        if num < 0:
            raise ValueError("Negative numbers are not allowed in duration")

        if i == len(s):
            parsed_units.append((num, 's'))
            break

        unit = s[i]
        if unit in ['h', 'm', 's', 'd']:
            parsed_units.append((num, unit))
        else:
            raise ValueError(f"Unknown unit: {unit}")

        i += 1

    return parsed_units

def _accumulate_to_minutes(parsed_units: list[tuple[float, str]]) -> float:
    total_minutes = 0.0
    for num, unit in parsed_units:
        if unit == 'h':
            total_minutes += num * 60
        elif unit == 'm':
            total_minutes += num
        elif unit == 's':
            total_minutes += num / 60
        elif unit == 'd':
            total_minutes += num * 1440

    return total_minutes

